    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Mapper failure AND close failure: original mapper error wins.
  {
    const mapperError = new Error('mapper failed');
    const { source, state } = makeSource(['a'], { closeError: new Error('close failed') });
    const service = new EventService(source, () => { throw mapperError; });
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) { /* drain */ } })(),
      (error) => error === mapperError,
    );
    assert.equal(state.closes, 1);
  }

  // Consumer-injected throw: closed exactly once, injected error preserved.
  {
    const injected = new Error('injected');
    const { source, state } = makeSource(['a', 'b']);
    const service = new EventService(source);
    const iterator = service.stream();
    assert.deepEqual(await iterator.next(), { value: 'A', done: false });
    await assert.rejects(iterator.throw(injected), (error) => error === injected);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Injected throw AND close failure: the injected error wins.
  {
    const injected = new Error('injected');
    const { source, state } = makeSource(['a'], { closeError: new Error('close failed') });
    const service = new EventService(source);
    const iterator = service.stream();
    await iterator.next();
    await assert.rejects(iterator.throw(injected), (error) => error === injected);
    assert.equal(state.closes, 1);
  }

  // Close failure on normal exhaustion propagates.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource(['a'], { closeError });
    const service = new EventService(source);
    const iterator = service.stream();
    assert.deepEqual(await iterator.next(), { value: 'A', done: false });
    await assert.rejects(iterator.next(), (error) => error === closeError);
    assert.equal(state.reads, 2);
    assert.equal(state.closes, 1);
  }

  // Close failure on consumer break propagates.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource(['a', 'b'], { closeError });
    const service = new EventService(source);
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) break; })(),
      (error) => error === closeError,
    );
    assert.equal(state.closes, 1);
  }

  // Close failure on consumer return propagates.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource(['a'], { closeError });
    const service = new EventService(source);
    const iterator = service.stream();
    await iterator.next();
    await assert.rejects(iterator.return(), (error) => error === closeError);
    assert.equal(state.closes, 1);
  }

  // A throw() into an unopened generator must not open, read or close anything.
  {
    const injected = new Error('injected');
    const { source, state } = makeSource(['a']);
    const service = new EventService(source);
    const iterator = service.stream();
    await assert.rejects(iterator.throw(injected), (error) => error === injected);
    assert.equal(state.opens, 0);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);
  }

  // Open failure leaves nothing to close.
  {
    const openError = new Error('open failed');
    const { source, state } = makeSource(['a'], { openError });
    const service = new EventService(source);
    await assert.rejects(
      (async () => { for await (const _ of service.stream()) { /* drain */ } })(),
      (error) => error === openError,
    );
    assert.equal(state.opens, 1);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);
  }
}

